import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
const oldNames={recordingPreview:'liveRecordingPreviewAsync',recordingApply:'liveRecordingApplyAsync',undo:'liveUndoAsync',realtimePreview:'liveRealtimeArmPreviewAsync',realtimeApply:'liveRealtimeArmApplyAsync',disarm:'liveRealtimeDisarmAsync',stats:'liveRealtimeStatsAsync'};
function clean(v){v=JSON.parse(JSON.stringify(v));function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&/^(trackset_)/.test(w))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text)}catch{}walk(v);return v;}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function change(root,path,value,remove=false){let at=root;for(const key of path.slice(0,-1))at=at[key];if(remove)delete at[path.at(-1)];else at[path.at(-1)]=structuredClone(value);}
function setup(config={}){
 const sim=new DeterministicLiveSimulator();const other=structuredClone(sim.state.tracks[0]);Object.assign(other,{ref:'track:other',name:'Other',objectIdentity:'simulator:track:other',devices:[],clips:[],clipSlots:[]});for(const key of ['volumeRef','panRef','cueRef','volumeIdentity','panIdentity','cueIdentity'])other.mixer[key]=null;other.mixer.sendRefs=[];other.mixer.sendIdentities=[];other.mixer.sends=[];sim.state.tracks.push(other);sim.state.tracks.forEach(t=>t.armed=true);for(const p of config.patches??[])change(sim.state,p.path,p.value,p.remove);
 const calls=[],cache=new Map(),overrides={provenance:'real-live',registryHash:'a'.repeat(64),...config.status};let fault='',fired=false,armed=false,pending,controller;
 const status=()=>({...sim.status(),...overrides,operations:overrides.operations??[...sim.status().operations,'realtime.arm','realtime.disarm','realtime.stats']});
 function once(){if(fired)return false;fired=true;return true;}
 async function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(c?.transactionId&&cache.has(key))return cache.get(key);
 if(['before','cancel','refusal'].includes(fault)&&once())throw fault==='refusal'?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error(fault==='cancel'?'operation cancelled before dispatch':'injected operation failure');
 if(fault==='during-invoke')controller?.abort();if(fault==='no-effect'&&once())return {changed:true};
 let result;if(i.operation==='realtime.arm'){armed=true;await new Promise(r=>setTimeout(r,1));result={host:'127.0.0.1',port:9766,token:'t'.repeat(32),expiresAt:Date.now()+i.args.ttlMs,channels:i.args.channels,parameterRefs:i.args.parameterRefs,packetLimitBytes:512,ratePerSecond:64,burst:16};if(config.endpoint)Object.assign(result,config.endpoint);}else if(i.operation==='realtime.disarm'){armed=false;result={armed:false};}else if(i.operation==='realtime.stats')result={armed,accepted:2,pending:0};else {if(fault==='delayed'&&!fired)pending=structuredClone(sim.state.playback);result=sim.invoke(i);}
 if(fault==='null'&&once())result=null;if(fault==='false'&&once())result={recording:'yes',armed:'no'};if(fault==='no-effect'&&once()){sim.state.playback.transport.sessionRecord=false;sim.state.playback.transport.arrangementRecord=false;}
 if(config.ack&&result&&typeof result==='object')Object.assign(result,config.ack);if(c?.transactionId)cache.set(key,result);if(fault==='after'&&once())throw Error('injected operation failure');return result;}
 const adapter={status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));if(fault==='read'&&once())throw Error('injected authoritative read failure');if(pending){const v=sim.snapshot();v.playback=pending;pending=undefined;fired=true;return v;}return sim.snapshotAsync(c,r);},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));if(r.kind==='session-playback'&&fault==='playback-read'&&once())throw Error('injected authoritative read failure');const result=await sim.discoverAsync(r,c);if(r.kind==='session-playback'&&pending){result.items=[pending];pending=undefined;fired=true;}return result},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));return sim.get(r)},invokeAsync:invoke,refreshStatusAsync:async c=>{calls.push(clean({method:'status',context:context(c)}));if(fault==='status'&&once())throw Error('injected status failure');if(fault==='during-status')controller?.abort();return status();}};
 return {host:new McpHost(adapter),sim,calls,overrides,get armed(){return armed},set fault(v){fault=v;fired=false},set controller(v){controller=v}};
}

const names={trackPreview:'liveTrackPropertiesPreviewAsync',trackApply:'liveTrackPropertiesApplyAsync',undo:'liveUndoAsync'};
const rows=[],workflows=[];
async function workflow(label,config,steps){const a=setup(config),results=[],states=[];let tx;async function call(step,id){const args=structuredClone(step.args??{});if(args.transactionId==='$transaction')args.transactionId=tx;const controller=new AbortController();a.controller=controller;if(step.abort)controller.abort();const result=await a.host[names[step.tool]](id,args,controller.signal);if(step.tool.endsWith('Preview')){try{tx=JSON.parse(result.result.content[0].text).transactionId}catch{}}return clean(result);}
 for(const step of steps){if(step.patch){change(a.sim.state,step.patch.path,step.patch.value,step.patch.remove);continue;}if(step.status){Object.assign(a.overrides,step.status);continue;}if(step.record){if(tx)Object.assign(a.host.clipLifecycleTransactions.get(tx),step.record);continue;}if('fault'in step){a.fault=step.fault;continue;}
 if(step.concurrent){const offset=results.length;results.push(...await Promise.all(step.concurrent.map((s,i)=>call(s,offset+i+1))));}else results.push(await call(step,results.length+1));states.push(tx?clean(a.host.clipLifecycleTransactions.get(tx)):null);}
 workflows.push({label,config,steps,results,states,calls:a.calls,final:clean({view:a.sim.state.view??null,transport:a.sim.state.playback.transport,locators:a.sim.state.arrangement.locators,track:a.sim.state.tracks[0]})});}
const apply=(family,key='apply-key',extra={})=>({tool:family+'Apply',args:{transactionId:'$transaction',confirmation:'apply',idempotencyKey:key},...extra});
const defaults={trackPreview:{ref:'track:track-1',colorIndex:10},trackApply:{transactionId:'missing',confirmation:'apply',idempotencyKey:'key'}};
for(const[tool,valid]of Object.entries(defaults)){const cases=[null,[],{},false,0,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const missing={...valid};delete missing[key];cases.push(missing);for(const value of [null,[],{},true,false,-1,0,0.5,1,69,70,'','x','x'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const a=setup();rows.push({tool,args,result:clean(await a.host[names[tool]](1,args))});}}
for(const scenario of ['normal','expire','epoch','disconnected','operation','apply-edit','apply-identity','apply-before','apply-after','apply-cancel','apply-refusal','apply-null','apply-false','apply-no-effect','apply-read','apply-status','preabort','undo-before','undo-after','undo-refusal','undo-null','undo-no-effect','undo-identity','undo-manual','undo-read','null-prior','missing-prior','null-color','missing-color','undo-key-set']){
 const config={};if(scenario==='disconnected')config.status={connected:false};if(scenario==='operation')config.status={operations:[]};if(scenario==='null-prior'||scenario==='missing-prior')config.patches=[{path:['tracks',0,'colorIndex'],value:null,remove:scenario==='missing-prior'}];if(scenario==='null-color'||scenario==='missing-color')config.patches=[{path:['tracks',0,'color'],value:null,remove:scenario==='missing-color'}];
 const steps=[{tool:'trackPreview',args:{ref:'track:track-1',colorIndex:10}}];if(scenario==='expire')steps.push({record:{expiresAt:0}});if(scenario==='epoch')steps.push({status:{epoch:99}});const manual={path:['tracks',0,'colorIndex'],value:5};const identity={path:['tracks',0,'objectIdentity'],value:'changed'};if(scenario==='apply-edit')steps.push({patch:manual});if(scenario==='apply-identity')steps.push({patch:identity});if(scenario==='undo-key-set')steps.push({record:{state:'uncertain',applyKey:'apply-key',undoKey:'undo-key'}});if(scenario.startsWith('apply-')&&!['apply-edit','apply-identity'].includes(scenario))steps.push({fault:scenario.slice(6)});steps.push(apply('track','apply-key',{abort:scenario==='preabort'}),apply('track','other-key'),apply('track'),{fault:''});if(scenario==='undo-identity')steps.push({patch:identity});if(scenario==='undo-manual')steps.push({patch:manual});if(scenario.startsWith('undo-')&&!['undo-identity','undo-manual','undo-key-set'].includes(scenario))steps.push({fault:scenario.slice(5)});for(const key of ['undo-key','other-key','undo-key'])steps.push({tool:'undo',args:{transactionId:'$transaction',confirmation:'undo',idempotencyKey:key}});await workflow(scenario,config,steps);
}
fs.writeFileSync(new URL('host-track-properties-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
